"use client";

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
  type ClipboardEvent,
  type HTMLAttributes,
  type InputHTMLAttributes,
  type MutableRefObject,
  type ReactNode,
} from "react";
import { motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { fontWeights } from "@/lib/font-weight";
import { useShape } from "@/lib/shape-context";
import { useSize, type SizeVariant } from "@/lib/size-context";
import { spring } from "@/lib/springs";

interface InputOTPContextValue {
  value: string;
  maxLength: number;
  activeIndex: number;
  selectionStart: number;
  selectionEnd: number;
  focused: boolean;
  disabled: boolean;
  readOnly: boolean;
  invalid: boolean;
  success: boolean;
  compact: boolean;
  reduceMotion: boolean;
  focusAt: (index: number) => void;
}

const InputOTPContext = createContext<InputOTPContextValue | null>(null);

function useInputOTP() {
  const context = useContext(InputOTPContext);
  if (!context) throw new Error("InputOTPSlot must be used inside InputOTP");
  return context;
}

export interface InputOTPProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "onChange" | "value" | "defaultValue" | "maxLength" | "size" | "type"
> {
  /** Number of code characters. Also controls the automatically-rendered slots. */
  maxLength?: number;
  /** Controlled code value. */
  value?: string;
  /** Initial code value for uncontrolled use. */
  defaultValue?: string;
  /** Called with the current code whenever it changes. */
  onChange?: (value: string) => void;
  /** Called whenever an edit changes the code to a complete value. */
  onComplete?: (value: string) => void;
  /** Show an invalid state and expose it to assistive technology. */
  invalid?: boolean;
  /** Show a successful verification state. */
  success?: boolean;
  /** Uses the shared 28px compact control step when set. */
  size?: SizeVariant;
  /** Numeric codes normalize Unicode digits and discard non-digits by default. Set to "none" for free-form codes. */
  filter?: "numeric" | "none";
  /** Override the native input's accessible name. */
  "aria-label"?: string;
  children?: ReactNode;
}

/** A one-input OTP control with composable visual slots. */
const InputOTP = forwardRef<HTMLInputElement, InputOTPProps>(
  (
    {
      maxLength: maxLengthProp = 6,
      value: valueProp,
      defaultValue = "",
      onChange,
      onComplete,
      invalid: invalidProp = false,
      success = false,
      size,
      className,
      children,
      disabled = false,
      readOnly = false,
      autoComplete = "one-time-code",
      inputMode = "numeric",
      "aria-label": ariaLabel = "One-time code",
      "aria-invalid": ariaInvalidProp,
      onFocus,
      onBlur,
      onSelect,
      onPaste,
      filter: filterProp,
      ...inputProps
    },
    forwardedRef,
  ) => {
    const maxLength = Number.isFinite(maxLengthProp) ? Math.max(1, Math.trunc(maxLengthProp)) : 6;
    const filter = filterProp ?? (inputMode === "text" ? "none" : "numeric");
    const normalizeValue = useCallback(
      (rawValue: string) => normalizeOTPValue(rawValue, filter).slice(0, maxLength),
      [filter, maxLength],
    );
    const normalizedDefaultValue = normalizeValue(defaultValue);
    const inputRef = useRef<HTMLInputElement | null>(null);
    const initialValue = useRef(normalizedDefaultValue);
    initialValue.current = normalizedDefaultValue;
    const [internalValue, setInternalValue] = useState(normalizedDefaultValue);
    const [focused, setFocused] = useState(false);
    const [selection, setSelection] = useState({ start: 0, end: 0 });
    const controlled = valueProp !== undefined;
    const value = normalizeValue(String(controlled ? valueProp : internalValue));
    const sizeClasses = useSize(size);
    const reduceMotion = useReducedMotion() ?? false;
    const invalid = invalidProp || ariaInvalidProp === true || ariaInvalidProp === "true";

    const setInputRef = useCallback(
      (node: HTMLInputElement | null) => {
        inputRef.current = node;
        if (typeof forwardedRef === "function") forwardedRef(node);
        else if (forwardedRef)
          (forwardedRef as MutableRefObject<HTMLInputElement | null>).current = node;
      },
      [forwardedRef],
    );

    const updateValue = useCallback(
      (nextValue: string) => {
        const next = normalizeValue(nextValue);
        if (!controlled) setInternalValue(next);
        onChange?.(next);
        if (next.length === maxLength && next !== value) onComplete?.(next);
      },
      [controlled, maxLength, normalizeValue, onChange, onComplete, value],
    );

    const focusAt = useCallback(
      (index: number) => {
        if (disabled) return;
        const input = inputRef.current;
        if (!input) return;
        input.focus();
        const start = index < value.length ? index : Math.min(index, value.length);
        const end = index < value.length ? start + 1 : start;
        input.setSelectionRange(start, end);
        setSelection({ start, end });
      },
      [disabled, value.length],
    );

    useEffect(() => {
      if (controlled) return;
      const form = inputRef.current?.form;
      if (!form) return;
      const reset = (event: Event) => {
        queueMicrotask(() => {
          if (event.defaultPrevented) return;
          setInternalValue(initialValue.current);
          setSelection({ start: 0, end: 0 });
        });
      };
      form.addEventListener("reset", reset);
      return () => form.removeEventListener("reset", reset);
    }, [controlled, inputProps.form]);

    const updateSelection = useCallback(() => {
      const input = inputRef.current;
      if (input) {
        setSelection({ start: input.selectionStart ?? 0, end: input.selectionEnd ?? 0 });
      }
    }, []);

    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
      updateValue(event.currentTarget.value);
      updateSelection();
    };

    const handlePaste = (event: ClipboardEvent<HTMLInputElement>) => {
      onPaste?.(event);
      if (event.defaultPrevented || disabled || readOnly) return;
      const pasted = event.clipboardData.getData("text");
      // Preserve ordinary native paste. When separators are present, insert a
      // cleaned code into the current selection so spaces/hyphens don't occupy slots.
      if (!pasted) return;
      const input = event.currentTarget;
      const start = input.selectionStart ?? value.length;
      const end = input.selectionEnd ?? start;
      const cleaned = normalizeValue(pasted.replace(/[\s-]/g, ""));
      const hasSeparators = /[\s-]/.test(pasted);
      const needsNormalization = cleaned !== pasted;
      const replacesCode = cleaned.length >= maxLength;
      if (!hasSeparators && !needsNormalization && !replacesCode) return;
      event.preventDefault();
      const next = replacesCode
        ? cleaned
        : normalizeValue(`${value.slice(0, start)}${cleaned}${value.slice(end)}`);
      updateValue(next);
      const caret = replacesCode ? next.length : Math.min(start + cleaned.length, next.length);
      requestAnimationFrame(() => {
        inputRef.current?.setSelectionRange(caret, caret);
        updateSelection();
      });
    };

    const contextValue = useMemo<InputOTPContextValue>(
      () => ({
        value,
        maxLength,
        activeIndex: Math.min(selection.end, maxLength - 1),
        selectionStart: selection.start,
        selectionEnd: selection.end,
        focused,
        disabled,
        readOnly,
        invalid,
        success: success && !invalid,
        compact: sizeClasses.variant === "compact",
        reduceMotion,
        focusAt,
      }),
      [
        value,
        maxLength,
        selection,
        focused,
        disabled,
        readOnly,
        invalid,
        success,
        sizeClasses.variant,
        reduceMotion,
        focusAt,
      ],
    );

    const slots = Array.from({ length: maxLength }, (_, index) => (
      <InputOTPSlot key={index} index={index} />
    ));

    return (
      <InputOTPContext.Provider value={contextValue}>
        <div
          className={cn("relative inline-flex max-w-full", className)}
          data-invalid={invalid || undefined}
          data-success={(success && !invalid) || undefined}
          onPointerDown={(event) => {
            if (
              event.target instanceof Element &&
              event.target.closest('[data-slot="input-otp-slot"]')
            )
              return;
            event.preventDefault();
            focusAt(value.length);
          }}
        >
          <input
            {...inputProps}
            ref={setInputRef}
            type="text"
            value={value}
            maxLength={maxLength}
            disabled={disabled}
            readOnly={readOnly}
            autoComplete={autoComplete}
            inputMode={inputMode}
            aria-label={ariaLabel}
            aria-invalid={invalidProp || ariaInvalidProp || undefined}
            onChange={handleChange}
            onFocus={(event) => {
              setFocused(true);
              updateSelection();
              onFocus?.(event);
            }}
            onBlur={(event) => {
              setFocused(false);
              onBlur?.(event);
            }}
            onSelect={(event) => {
              updateSelection();
              onSelect?.(event);
            }}
            onPaste={handlePaste}
            className="pointer-events-none absolute inset-0 z-10 h-full w-full cursor-text appearance-none border-0 bg-transparent p-0 text-transparent opacity-0 shadow-none outline-none ring-0 [caret-color:transparent]"
            style={{
              WebkitAppearance: "none",
              appearance: "none",
              border: 0,
              outline: "none",
              boxShadow: "none",
              backgroundColor: "transparent",
              color: "transparent",
              caretColor: "transparent",
              ...inputProps.style,
            }}
          />
          {children ?? <InputOTPGroup>{slots}</InputOTPGroup>}
        </div>
      </InputOTPContext.Provider>
    );
  },
);

InputOTP.displayName = "InputOTP";

export interface InputOTPGroupProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
}

const InputOTPGroup = forwardRef<HTMLDivElement, InputOTPGroupProps>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn("flex items-center gap-1", className)} {...props} />
  ),
);
InputOTPGroup.displayName = "InputOTPGroup";

export interface InputOTPSlotProps extends HTMLAttributes<HTMLDivElement> {
  index: number;
}

const InputOTPSlot = forwardRef<HTMLDivElement, InputOTPSlotProps>(
  ({ index, className, children, ...props }, ref) => {
    const {
      value,
      activeIndex,
      selectionStart,
      selectionEnd,
      focused,
      disabled,
      invalid,
      success,
      compact,
      reduceMotion,
      focusAt,
    } = useInputOTP();
    const { onPointerDown, ...slotProps } = props;
    const shape = useShape();
    const char = value[index] ?? "";
    const selected =
      selectionStart !== selectionEnd && index >= selectionStart && index < selectionEnd;
    const active =
      focused && !disabled && (selectionStart !== selectionEnd ? selected : activeIndex === index);
    const tone = invalid
      ? "border-destructive text-destructive"
      : success
        ? "border-[color:var(--success)] text-[color:var(--success)]"
        : "border-border text-foreground";

    return (
      <div
        ref={ref}
        data-slot="input-otp-slot"
        data-active={active || undefined}
        aria-hidden="true"
        onPointerDown={(event) => {
          event.preventDefault();
          event.stopPropagation();
          if (!disabled) focusAt(index);
          onPointerDown?.(event);
        }}
        className={cn(
          "relative grid shrink-0 place-items-center border bg-background font-mono tabular-nums",
          shape.input,
          compact ? "h-7 w-7 text-[12px]" : "h-9 w-9 text-[14px]",
          tone,
          active &&
            !invalid &&
            !success &&
            "z-[1] border-[var(--focus-ring,#6B97FF)] ring-2 ring-[var(--focus-ring,#6B97FF)]",
          active && invalid && "z-[1] border-destructive ring-2 ring-destructive/20",
          active &&
            success &&
            "z-[1] border-[color:var(--success)] ring-2 ring-[color:var(--success)]/20",
          disabled && "cursor-not-allowed opacity-50",
          className,
        )}
        {...slotProps}
      >
        {char && (
          <motion.span
            key={`${index}-${char}`}
            initial={reduceMotion ? false : { opacity: 0, scale: 0.82, y: 2 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            transition={spring.fast}
            style={{ fontVariationSettings: fontWeights.semibold }}
          >
            {children ?? char}
          </motion.span>
        )}
        {!char && children}
      </div>
    );
  },
);
InputOTPSlot.displayName = "InputOTPSlot";

export interface InputOTPSeparatorProps extends HTMLAttributes<HTMLSpanElement> {
  children?: ReactNode;
}

const InputOTPSeparator = forwardRef<HTMLSpanElement, InputOTPSeparatorProps>(
  ({ className, children, ...props }, ref) => (
    <span
      ref={ref}
      aria-hidden="true"
      className={cn("px-2 text-muted-foreground", className)}
      {...props}
    >
      {children ?? "–"}
    </span>
  ),
);
InputOTPSeparator.displayName = "InputOTPSeparator";

export { InputOTP, InputOTPGroup, InputOTPSlot, InputOTPSeparator };
export default InputOTP;

function normalizeOTPValue(value: string, filter: "numeric" | "none") {
  const normalizedDigits = Array.from(value.normalize("NFKC"), (character) => {
    const codePoint = character.codePointAt(0) ?? 0;
    if (codePoint >= 0x0660 && codePoint <= 0x0669) {
      return String(codePoint - 0x0660);
    }
    if (codePoint >= 0x06f0 && codePoint <= 0x06f9) {
      return String(codePoint - 0x06f0);
    }
    return character;
  }).join("");
  return filter === "numeric" ? normalizedDigits.replace(/[^0-9]/g, "") : normalizedDigits;
}
